#define TAU (6.283185307)
#define HEX(x) (vec3((x >> 16) & 255, (x >> 8) & 255, x & 255) / 255.0)

// Adjust overall animation speed.
const float TIME_MULTIPLIER = 0.1;

// -------------------------------------------------------------------------
// Fast approximations for trigonometric functions.
// These functions sacrifice a bit of accuracy for speed.

// Fast sine approximation using a polynomial.
// This function wraps the input into [-PI, PI] then uses an efficient formula.
float fastSin(float x) {
    const float PI = 3.14159265;
    // Wrap x into [-PI, PI]
    x = mod(x + PI, TAU) - PI;
    // Compute sine approximation.
    const float B = 4.0 / PI;
    const float C = -4.0 / (PI * PI);
    float y = B * x + C * x * abs(x);
    // Extra precision using a parabolic correction.
    const float P = 0.225;
    y = P * (y * abs(y) - y) + y;
    return y;
}

// Fast cosine using the sine approximation.
float fastCos(float x) {
    return fastSin(x + 1.57079633);
}

// Returns a 2D unit vector using our fast approximated sine and cosine.
vec2 angleVec(float theta) {
    return vec2(fastCos(theta), fastSin(theta));
}
// -------------------------------------------------------------------------


// -------------------------------------------------------------------------
// Approximated easing function.
// Instead of the quintic smoothstep (6t^5 - 15t^4 + 10t^3),
// we use the cubic smoothstep: 3t^2 - 2t^3.
float ease(float t) {
    t = clamp(t, 0.0, 1.0);
    return t * t * (3.0 - 2.0 * t);
}
// -------------------------------------------------------------------------


// The permutation table and associated functions (rand, randxy) are unchanged.
const int permutation[256] = int[](
