    107, 34, 8, 201, 3, 42, 119, 210, 103, 41, 79, 233, 106, 254, 11, 222,
    209, 171, 46, 234, 118, 81, 37, 162, 61, 177, 132, 202, 244, 116, 123, 158,
    122, 192, 155, 121, 51, 74, 15, 57, 198, 97, 239, 129, 185, 112, 241, 19
);

int rand(int x) {
    return permutation[x & 255];
}

float randxy(vec2 xy, float t) {
    return float(rand(rand(rand(int(floor(xy.x))) + int(floor(xy.y))) + int(floor(t)))) / 255.0;
}

// Posterize: Precompute col * steps.
vec3 posterize(vec3 col, float thres) {
    const float steps = 2.0;
    vec3 v = col * steps;
    return (floor(v) + step(vec3(thres), fract(v))) / steps;
}

// Crosshatch: Uses bit‑operations (already inexpensive).
float crosshatch(vec2 xyf) {
    ivec2 xy = ivec2(xyf) & 3;
    return float(1 + ((xy.y >> 1) & 1) + ((xy.x & 2) ^ (xy.y & 2)) +
                 ((xy.y & 1) << 2) + (((xy.x & 1) ^ (xy.y & 1)) << 3)) / 16.0;
}

// Ripple: Compute length(uv) once and use branchless normalization.
float ripple(vec2 uv, vec2 lightDir, float scale, float time) {
    float len = length(uv);
    float f = fract(len * scale - time);
    float eased = ease(1.0 - abs(1.0 - f * 2.0));
    vec2 nUV = uv / max(len, 1e-6);
    return eased * 0.5 * dot(lightDir, nUV * ease(len * scale * 0.25));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Scale time.
    float st = iTime * TIME_MULTIPLIER;
    float time = fract(st / 4.0);
    float tauTime = TAU * time;
    float rippleTime = time * 7.0; // timeScale = 7.0

    // Precompute resolution-based quantities.
    vec2 res = iResolution.xy;
    float invResLen = 1.0 / length(res);
    vec2 uv = (2.0 * fragCoord - res) * invResLen;
    float uvLen = length(uv);

    // Compute light angle using our fastSin approximation.
    float lightAngle = 1.7 + 0.45 * fastSin(2.0 * uv.x * TAU);
    vec2 la  = angleVec(lightAngle);
    vec2 laP = angleVec(lightAngle + 0.1);
    vec2 laM = angleVec(lightAngle - 0.1);

    // Precompute centers from a single base value.
    float base = 2.5 + tauTime;
    vec2 center0 = 0.1 * angleVec(base);
    vec2 center1 = 0.1 * angleVec(base + TAU / 3.0);
    vec2 center2 = 0.1 * angleVec(base - TAU / 3.0);

    // Distort uv using a ripple.
    uv += ripple(uv, la, 8.0, rippleTime) * vec2(0.05, 0.2) * uvLen;

    // Accumulate color from three offset ripple contributions.
    vec3 col = vec3(0.0);
    col += ripple(uv - center0, laP, 8.0, rippleTime) * vec3( 0.5,  0.5, -1.0);
    col += ripple(uv - center1, la,  8.0, rippleTime) * vec3(-1.0,  0.5,  0.5);
    col += ripple(uv - center2, laM, 8.0, rippleTime) * vec3( 0.5, -1.0,  0.5);

    // Precompute mod-offset for the crosshatch.
    vec2 modOffset = mod(st * 50.0, 2.0) * vec2(1.0, 2.0);
    col = posterize(col * 1.3 + 0.5, crosshatch(fragCoord + modOffset));

    // Final color adjustment.
    col = vec3(0.6, 0.76, 0.8) + (col - 0.5) * 0.3;
    fragColor = vec4(col, 1.0);
}
